        "java" => Some(tree_sitter_java::LANGUAGE.into()),
        "kotlin" => Some(tree_sitter_kotlin_ng::LANGUAGE.into()),
        "fortran" => Some(tree_sitter_fortran::LANGUAGE.into()),
        "csharp" => Some(tree_sitter_c_sharp::LANGUAGE.into()),
        "javascript" => Some(tree_sitter_javascript::LANGUAGE.into()),
        "css" => Some(tree_sitter_css::LANGUAGE.into()),
        "yaml" => Some(tree_sitter_yaml::LANGUAGE.into()),
        "swift" => Some(tree_sitter_swift::LANGUAGE.into()),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_get_language_info_known() {
        // Happy path: known languages return Some
        assert!(
            get_language_info("rust").is_some(),
            "expected Some for 'rust'"
        );
        assert!(get_language_info("go").is_some(), "expected Some for 'go'");
        assert!(
            get_language_info("python").is_some(),
            "expected Some for 'python'"
        );
    }

    #[test]
    fn test_get_language_info_unknown() {
        // Edge case: unknown language returns None
        assert!(
            get_language_info("cobol").is_none(),
            "expected None for 'cobol'"
        );
    }

    #[test]
    fn test_get_ts_language_known() {
        // Happy path: known language returns Some
        assert!(
            get_ts_language("rust").is_some(),
            "expected Some for 'rust'"
        );
    }

    #[test]
    fn test_get_ts_language_unknown() {
        // Edge case: unknown language returns None
        assert!(
            get_ts_language("cobol").is_none(),
            "expected None for 'cobol'"
        );
    }

    #[test]
    fn test_get_language_info_covers_remaining_registered_languages() {
        // Table-driven: every registered language key resolves with expected metadata
        for (lang, has_references, has_imports) in [
            ("tsx", true, true),
            ("fortran", true, true),
            ("markdown", false, false),
            ("css", false, true),
            ("yaml", false, false),
        ] {
            let info = get_language_info(lang);
            assert!(info.is_some(), "expected Some for '{lang}'");
            let info = info.unwrap();
            assert_eq!(info.name, lang);
            assert_eq!(
                info.reference_query.is_some(),
                has_references,
                "reference_query mismatch for '{lang}'"
            );
            assert_eq!(
                info.import_query.is_some(),
                has_imports,
                "import_query mismatch for '{lang}'"
            );
            assert!(
                get_ts_language(lang).is_some() || lang == "markdown",
                "expected tree-sitter language for '{lang}'"
            );
        }
    }
}

